import{attachInputText,readInputText}from"#internal/input-text.js";import{createChannelAddressFn}from"#channel/channel-address.js";import{parseAnswers}from"#shared/input.js";function createChannelOperations(e){let t=createChannelAddressFn(e);return{from(e){let n=t(e);return{async send(e,t){return await n.deliver(attachInputText({context:t.context,history:t.history,message:e,outputSchema:t.outputSchema,state:t.state},readInputText(t)),t)},async create(e){return await n.create(e)},async respond(e,t){if(e.length===0)throw Error(`respond() requires at least one answer.`);let r=parseAnswers(e);return await n.deliver({context:t.context,outputSchema:t.outputSchema,answers:r,state:t.state},t)},async cancel(e){return await n.cancel(e)},async compact(e){return await n.compact(e)},async clear(e){return await n.clear(e)},async end(e){return await n.end(e)}}},async resolveSession(e){return await t(e).resolveSession()}}}export{createChannelOperations};